package cc.huevia.ui;

import android.app.*;
import android.content.*;
import android.content.res.*;
import android.graphics.*;
import android.os.Bundle;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import cc.huevia.ncp.PhotoGeometry;
import java.util.Locale;
import java.util.function.Consumer;

/** A tentative, full-canvas crop workspace. Back/cancel never mutates the photo's draft. */
public final class PhotoCropDialog extends Dialog {
    private static final int TEXT=0xfff4f5f7,BLUE=0xff8dbbff;
    private final Activity activity;private final Bitmap source;private final Consumer<PhotoGeometry> commit;
    private PhotoGeometry geometry;private CropCanvas crop;private TextView summary,angleValue;private SeekBar slider;
    private double ratio=-1;private boolean updating;private String ratioName="自由";
    public PhotoCropDialog(Activity activity,Bitmap source,PhotoGeometry geometry,Consumer<PhotoGeometry> commit){super(activity,cc.huevia.R.style.AppThemeDark);this.activity=activity;this.source=source;this.geometry=geometry;this.commit=commit;}
    public PhotoGeometry geometry(){return geometry;}
    @Override protected void onCreate(Bundle saved){super.onCreate(saved);requestWindowFeature(Window.FEATURE_NO_TITLE);
        LinearLayout root=column();root.setBackgroundColor(0xff141415);
        LinearLayout top=row();top.addView(button("取消",()->dismiss()),new LinearLayout.LayoutParams(dp(64),dp(48)));TextView title=text("构图",16);title.setGravity(Gravity.CENTER);top.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));Button apply=button("应用",()->{commit.accept(geometry);dismiss();});apply.setTextColor(BLUE);top.addView(apply,new LinearLayout.LayoutParams(dp(64),dp(48)));root.addView(top);
        boolean landscape=activity.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE;
        LinearLayout body=new LinearLayout(activity);body.setOrientation(landscape?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
        crop=new CropCanvas();body.addView(crop,landscape?new LinearLayout.LayoutParams(0,-1,1):new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout controls=column();controls.setPadding(dp(10),0,dp(10),dp(8));controls.setBackgroundColor(0xff0b0b0b);
        HorizontalScrollView ratios=new HorizontalScrollView(activity);ratios.setHorizontalScrollBarEnabled(false);LinearLayout choices=row();ratios.addView(choices);
        String[] labels={"原比例","自由","1:1","4:3","3:2","9:16"};double[] values={0,-1,1,4.0/3,1.5,9.0/16};
        for(int i=0;i<labels.length;i++){String label=labels[i];double value=values[i];Button b=button(label,()->{ratio=value;ratioName=label;fitRatio();for(int j=0;j<choices.getChildCount();j++){Button item=(Button)choices.getChildAt(j);item.setTextColor(item.getText().toString().equals(label)?BLUE:TEXT);item.setSelected(item.getText().toString().equals(label));}});b.setSingleLine(true);b.setTextColor(label.equals("自由")?BLUE:TEXT);choices.addView(b,new LinearLayout.LayoutParams(dp(70),dp(48)));}controls.addView(ratios,new LinearLayout.LayoutParams(-1,dp(48)));
        LinearLayout actions=row();Button rotate=button("旋转 90°",()->{geometry=geometry.rotate();fitRatio();});rotate.setCompoundDrawablesRelativeWithIntrinsicBounds(icon(AppIcon.Kind.ROTATE),null,null,null);actions.addView(rotate,new LinearLayout.LayoutParams(0,dp(48),1));Button reset=button("重置构图",()->{geometry=PhotoGeometry.NONE;ratio=-1;ratioName="自由";updating=true;slider.setProgress(450);updating=false;for(int j=0;j<choices.getChildCount();j++){Button item=(Button)choices.getChildAt(j);item.setTextColor(item.getText().toString().equals("自由")?BLUE:TEXT);item.setSelected(item.getText().toString().equals("自由"));}changed();});actions.addView(reset,new LinearLayout.LayoutParams(0,dp(48),1));controls.addView(actions);
        LinearLayout angle=row();TextView label=text("拉直",13);angle.addView(label,new LinearLayout.LayoutParams(dp(40),dp(48)));slider=new SeekBar(activity);slider.setMax(900);slider.setProgress(geometry.angle+450);slider.setKeyProgressIncrement(1);slider.setProgressTintList(ColorStateList.valueOf(BLUE));slider.setThumbTintList(ColorStateList.valueOf(BLUE));angle.addView(slider,new LinearLayout.LayoutParams(0,dp(48),1));angleValue=text("",12);angleValue.setGravity(Gravity.CENTER);angle.addView(angleValue,new LinearLayout.LayoutParams(dp(60),dp(48)));controls.addView(angle);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user&&!updating){geometry=geometry.straighten(p-450);changed();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
        summary=text("",12);summary.setGravity(Gravity.CENTER);controls.addView(summary,new LinearLayout.LayoutParams(-1,dp(40)));TextView hint=text("拖动四角裁剪，框内拖动移动位置",12);hint.setTextColor(0xffadb6c3);hint.setGravity(Gravity.CENTER);controls.addView(hint,new LinearLayout.LayoutParams(-1,dp(32)));
        if(landscape){ScrollView scroll=new ScrollView(activity);scroll.addView(controls);body.addView(scroll,new LinearLayout.LayoutParams(dp(300),-1));}else body.addView(controls,new LinearLayout.LayoutParams(-1,-2));
        root.setOnApplyWindowInsetsListener((v,insets)->{int l,t,r,b;if(android.os.Build.VERSION.SDK_INT>=30){Insets safe=insets.getInsetsIgnoringVisibility(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());l=safe.left;t=safe.top;r=safe.right;b=safe.bottom;}else{l=insets.getStableInsetLeft();t=insets.getStableInsetTop();r=insets.getStableInsetRight();b=insets.getStableInsetBottom();}root.setPadding(l,t,r,b);return insets;});setContentView(root);Window window=getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setLayout(-1,-1);}root.requestApplyInsets();changed();
    }
    @Override public void show(){super.show();if(getWindow()!=null)getWindow().setLayout(-1,-1);}
    private void fitRatio(){
        if(ratio<0){changed();return;}
        PhotoGeometry.Plan p=geometry.fullFrame().plan(source.getWidth(),source.getHeight(),1);
        double normalized=ratio==0?1:ratio*p.frameHeight/p.frameWidth;
        double w=Math.min(1,normalized),h=w/normalized;
        double cx=(geometry.left+geometry.right)/(2.0*PhotoGeometry.UNIT),cy=(geometry.top+geometry.bottom)/(2.0*PhotoGeometry.UNIT);
        double l=Math.max(0,Math.min(1-w,cx-w/2)),t=Math.max(0,Math.min(1-h,cy-h/2));geometry=geometry.crop(l,t,l+w,t+h);changed();
    }
    private void changed(){if(crop==null)return;summary.setText(String.format(Locale.ROOT,"%s · 保留画面 %.0f%%",ratioName,(geometry.right-geometry.left)/(double)PhotoGeometry.UNIT*(geometry.bottom-geometry.top)/PhotoGeometry.UNIT*100));angleValue.setText(String.format(Locale.ROOT,"%.1f°",geometry.angle/10.0));slider.setContentDescription("拉直角度，"+angleValue.getText()+"，范围负45至45度");crop.setContentDescription("裁剪框。拖动四角调整大小，框内拖动移动。方向键移动，加减号缩放。"+ratioName);crop.invalidate();}
    private final class CropCanvas extends View {
        private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);private final RectF frame=new RectF(),box=new RectF();
        private final RectF start=new RectF();private float downX,downY;private int handle=-2;
        CropCanvas(){super(activity);setFocusable(true);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);}
        @Override protected void onDraw(Canvas c){super.onDraw(c);PhotoGeometry.Plan plan=geometry.fullFrame().plan(source.getWidth(),source.getHeight(),1);float scale=Math.min((getWidth()-dp(24))/(float)plan.width,(getHeight()-dp(24))/(float)plan.height);if(scale<=0)return;float w=plan.width*scale,h=plan.height*scale;frame.set((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);int save=c.save();c.clipRect(frame);c.translate(frame.left,frame.top);c.scale(scale,scale);Matrix matrix=new Matrix();matrix.setValues(plan.matrix());paint.setColor(Color.WHITE);paint.setStyle(Paint.Style.FILL);c.drawBitmap(source,matrix,paint);c.restoreToCount(save);
            box.set(frame.left+frame.width()*geometry.left/PhotoGeometry.UNIT,frame.top+frame.height()*geometry.top/PhotoGeometry.UNIT,frame.left+frame.width()*geometry.right/PhotoGeometry.UNIT,frame.top+frame.height()*geometry.bottom/PhotoGeometry.UNIT);
            paint.setColor(0x99000000);c.drawRect(frame.left,frame.top,frame.right,box.top,paint);c.drawRect(frame.left,box.bottom,frame.right,frame.bottom,paint);c.drawRect(frame.left,box.top,box.left,box.bottom,paint);c.drawRect(box.right,box.top,frame.right,box.bottom,paint);
            paint.setColor(0xccffffff);paint.setStrokeWidth(dp(1));paint.setStyle(Paint.Style.STROKE);c.drawRect(box,paint);paint.setColor(0x66ffffff);for(int i=1;i<3;i++){c.drawLine(box.left+box.width()*i/3,box.top,box.left+box.width()*i/3,box.bottom,paint);c.drawLine(box.left,box.top+box.height()*i/3,box.right,box.top+box.height()*i/3,paint);}paint.setColor(BLUE);paint.setStrokeWidth(dp(3));float arm=dp(18);for(int i=0;i<4;i++){float x=i%2==0?box.left:box.right,y=i<2?box.top:box.bottom;c.drawLine(x,y,x+(i%2==0?arm:-arm),y,paint);c.drawLine(x,y,x,y+(i<2?arm:-arm),paint);}paint.setStyle(Paint.Style.FILL);
        }
        @Override public boolean onTouchEvent(MotionEvent event){if(frame.width()<=0)return false;float x=event.getX(),y=event.getY();int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){handle=-2;float best=dp(30);for(int i=0;i<4;i++){float cx=i%2==0?box.left:box.right,cy=i<2?box.top:box.bottom;float distance=(float)Math.hypot(x-cx,y-cy);if(distance<best){best=distance;handle=i;}}if(handle==-2&&box.contains(x,y))handle=-1;if(handle==-2)return false;start.set(geometry.left/(float)PhotoGeometry.UNIT,geometry.top/(float)PhotoGeometry.UNIT,geometry.right/(float)PhotoGeometry.UNIT,geometry.bottom/(float)PhotoGeometry.UNIT);downX=x;downY=y;getParent().requestDisallowInterceptTouchEvent(true);return true;}
            if(handle== -2)return false;if(action==MotionEvent.ACTION_MOVE){float dx=(x-downX)/frame.width(),dy=(y-downY)/frame.height();RectF next=new RectF(start);if(handle== -1){dx=Math.max(-start.left,Math.min(1-start.right,dx));dy=Math.max(-start.top,Math.min(1-start.bottom,dy));next.offset(dx,dy);}else{boolean left=handle%2==0,top=handle<2;float ax=left?start.right:start.left,ay=top?start.bottom:start.top;float px=Math.max(0,Math.min(1,(left?start.left:start.right)+dx)),py=Math.max(0,Math.min(1,(top?start.top:start.bottom)+dy));float minX=Math.min(left?ax:1-ax,Math.min(.1f,dp(48)/frame.width())),minY=Math.min(top?ay:1-ay,Math.min(.1f,dp(48)/frame.height()));if(ratio>=0){double ar=ratio==0?frame.width()/frame.height():ratio;double nr=ar*frame.height()/frame.width();float maxW=Math.min(left?ax:1-ax,(float)((top?ay:1-ay)*nr));float w=Math.min(maxW,Math.max(Math.max(minX,(float)(minY*nr)),Math.max(Math.abs(px-ax),(float)(Math.abs(py-ay)*nr))));float h=(float)(w/nr);px=ax+(left?-w:w);py=ay+(top?-h:h);}else{px=left?Math.min(px,ax-minX):Math.max(px,ax+minX);py=top?Math.min(py,ay-minY):Math.max(py,ay+minY);}next.set(Math.min(ax,px),Math.min(ay,py),Math.max(ax,px),Math.max(ay,py));}geometry=geometry.crop(next.left,next.top,next.right,next.bottom);changed();return true;}
            if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){handle=-2;getParent().requestDisallowInterceptTouchEvent(false);performClick();return true;}return true;
        }
        @Override public boolean performClick(){super.performClick();return true;}
        private void resize(boolean smaller){double factor=smaller?.9:1.1,w=(geometry.right-geometry.left)/(double)PhotoGeometry.UNIT,h=(geometry.bottom-geometry.top)/(double)PhotoGeometry.UNIT;factor=Math.min(factor,Math.min(1/w,1/h));if(w*factor<.05||h*factor<.05)return;double cx=(geometry.left+geometry.right)/(2.0*PhotoGeometry.UNIT),cy=(geometry.top+geometry.bottom)/(2.0*PhotoGeometry.UNIT),l=Math.max(0,Math.min(1-w*factor,cx-w*factor/2)),t=Math.max(0,Math.min(1-h*factor,cy-h*factor/2));geometry=geometry.crop(l,t,l+w*factor,t+h*factor);changed();}
        @Override public void onInitializeAccessibilityNodeInfo(AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_FORWARD);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_BACKWARD);}
        @Override public boolean performAccessibilityAction(int action,Bundle arguments){if(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD||action==AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD){resize(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);return true;}return super.performAccessibilityAction(action,arguments);}
        @Override public boolean onKeyDown(int key,KeyEvent event){double dx=key==KeyEvent.KEYCODE_DPAD_LEFT?-.01:key==KeyEvent.KEYCODE_DPAD_RIGHT?.01:0,dy=key==KeyEvent.KEYCODE_DPAD_UP?-.01:key==KeyEvent.KEYCODE_DPAD_DOWN?.01:0;if(dx!=0||dy!=0){dx=Math.max(-geometry.left/(double)PhotoGeometry.UNIT,Math.min(1-geometry.right/(double)PhotoGeometry.UNIT,dx));dy=Math.max(-geometry.top/(double)PhotoGeometry.UNIT,Math.min(1-geometry.bottom/(double)PhotoGeometry.UNIT,dy));geometry=geometry.crop(geometry.left/(double)PhotoGeometry.UNIT+dx,geometry.top/(double)PhotoGeometry.UNIT+dy,geometry.right/(double)PhotoGeometry.UNIT+dx,geometry.bottom/(double)PhotoGeometry.UNIT+dy);changed();return true;}if(key==KeyEvent.KEYCODE_MINUS||key==KeyEvent.KEYCODE_PLUS||key==KeyEvent.KEYCODE_EQUALS){resize(key==KeyEvent.KEYCODE_MINUS);return true;}return super.onKeyDown(key,event);}
    }
    private android.graphics.drawable.Drawable icon(AppIcon.Kind kind){return new AppIcon(kind,TEXT,activity.getResources().getDisplayMetrics().density);}
    private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout v=new LinearLayout(activity);v.setOrientation(LinearLayout.VERTICAL);return v;}private LinearLayout row(){LinearLayout v=new LinearLayout(activity);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private TextView text(String s,int size){TextView v=new TextView(getContext());v.setText(s);v.setTextSize(size);v.setTextColor(TEXT);return v;}
    private Button button(String label,Runnable action){Button b=new Button(getContext());b.setText(label);b.setTextSize(13);b.setTextColor(TEXT);b.setAllCaps(false);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(6),0,dp(6),0);b.setBackground(new android.graphics.drawable.RippleDrawable(ColorStateList.valueOf(0x338dbbff),null,null));b.setOnClickListener(v->action.run());return b;}
}
